/* =========================================================
   1. MOVING BACKGROUND (soft gradient blobs drifting slowly)
   ========================================================= */
(function () {
  const canvas = document.getElementById("bg");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  let W, H;

  function resize() {
    W = canvas.width = window.innerWidth;
    H = canvas.height = window.innerHeight;
  }
  resize();
  window.addEventListener("resize", resize);

  // colors from your palette. light blue is rare + small = just a hint
  const colors = [
    "218,40,100",   // cerise
    "236,96,145",   // froly
    "254,103,110",  // bittersweet
    "253,143,82",   // coral
    "255,189,113",  // macaroni
    "242,167,190",  // wewak
    "154,225,226",  // morning glory (hint)
    "42,15,77"      // deep purple
  ];

  const blobs = colors.map((c, i) => {
    const isBlue = i === 6;
    return {
      x: Math.random() * W,
      y: Math.random() * H,
      r: (isBlue ? 0.14 : 0.28 + Math.random() * 0.2) * Math.max(W, H),
      vx: (Math.random() - 0.5) * 0.35,
      vy: (Math.random() - 0.5) * 0.35,
      c,
      a: isBlue ? 0.3 : 0.5
    };
  });

  function frame() {
    ctx.clearRect(0, 0, W, H);
    for (const b of blobs) {
      b.x += b.vx;
      b.y += b.vy;
      if (b.x < -b.r * 0.3 || b.x > W + b.r * 0.3) b.vx *= -1;
      if (b.y < -b.r * 0.3 || b.y > H + b.r * 0.3) b.vy *= -1;
      const g = ctx.createRadialGradient(b.x, b.y, 0, b.x, b.y, b.r);
      g.addColorStop(0, `rgba(${b.c},${b.a})`);
      g.addColorStop(1, `rgba(${b.c},0)`);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
    }
    requestAnimationFrame(frame);
  }
  frame();
})();

/* =========================================================
   2. PITCH-BLACK INTRO GATE  (index.html only)
      click the glowing middle -> circle opens up to the page
   ========================================================= */
(function () {
  const gate = document.getElementById("gate");
  const orb = document.getElementById("orb");
  if (!gate || !orb) return;

  let alreadyOpened = false;
  try { alreadyOpened = sessionStorage.getItem("opened") === "1"; } catch (e) {}

  if (alreadyOpened) {          // coming back from another page: skip the gate
    gate.classList.add("done");
    document.body.classList.add("opened");
    return;
  }

  document.body.classList.add("gated");

  function setHole(r) {
    const m = `radial-gradient(circle at 50% 50%, transparent ${r}px, #000 ${r + 2}px)`;
    gate.style.webkitMaskImage = m;
    gate.style.maskImage = m;
  }

  // little "pop" sound, made with the browser's own audio (no sound file needed)
  function playPop() {
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      const ac = new AC();
      const t = ac.currentTime;
      function blip(f0, f1, start, len, vol) {
        const o = ac.createOscillator(), g = ac.createGain();
        o.type = "sine";
        o.frequency.setValueAtTime(f0, t + start);
        o.frequency.exponentialRampToValueAtTime(f1, t + start + len);
        g.gain.setValueAtTime(0.0001, t + start);
        g.gain.exponentialRampToValueAtTime(vol, t + start + 0.008);
        g.gain.exponentialRampToValueAtTime(0.0001, t + start + len);
        o.connect(g); g.connect(ac.destination);
        o.start(t + start); o.stop(t + start + len + 0.02);
      }
      blip(620, 150, 0, 0.14, 0.32);         // the pop
      blip(900, 1500, 0.07, 0.10, 0.12);     // a tiny sparkle after it
      setTimeout(() => ac.close && ac.close(), 600);
    } catch (e) {}
  }

  let opening = false;
  orb.addEventListener("click", () => {
    if (opening) return;
    opening = true;
    playPop();
    try { sessionStorage.setItem("opened", "1"); } catch (e) {}

    const maxR = Math.hypot(window.innerWidth, window.innerHeight) / 2 + 40;
    const start = performance.now();
    const duration = 1700;

    // orb swells and fades while the hole opens
    orb.style.animation = "none";
    orb.style.transition = "transform 1.2s ease-in, opacity 1s";
    orb.style.transform = "scale(7)";
    orb.style.opacity = "0";
    const txt = document.getElementById("gate-text");
    if (txt) txt.style.opacity = "0";

    function tick(now) {
      const t = Math.min((now - start) / duration, 1);
      const eased = 1 - Math.pow(1 - t, 4);   // ease-out
      setHole(eased * maxR);
      if (t === 0 || t > 0.15) document.body.classList.remove("gated");
      if (t < 1) requestAnimationFrame(tick);
      else {
        gate.classList.add("done");
        document.body.classList.add("opened");
      }
    }
    requestAnimationFrame(tick);
  });
})();

/* =========================================================
   6. FLOWING BABY-BLUE RIBBONS (move through every page)
   ========================================================= */
(function () {
  const c = document.createElement("canvas");
  c.id = "ribbons";
  c.style.cssText = "position:fixed;inset:0;width:100%;height:100%;z-index:-1;pointer-events:none;";
  const bg = document.getElementById("bg");
  if (bg) bg.after(c); else document.body.prepend(c);
  const ctx = c.getContext("2d");
  let W, H, L;

  function resize() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    W = window.innerWidth; H = window.innerHeight;
    c.width = W * dpr; c.height = H * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    L = Math.hypot(W, H) * 1.15;
  }
  resize();
  window.addEventListener("resize", resize);

  // baby blue (#9AE1E2) + a lighter tint of it
  const BLUE = (a) => `rgba(154,225,226,${a})`;
  const PALE = (a) => `rgba(215,246,247,${a})`;

  // thick squiggly ribbons (like your blue squiggle reference)
  const thick = [
    { y: -0.28, a: 0.10, f: 0.0042, s: 0.35, p: 0.0, w: 54, col: BLUE(0.22), dash: [420, 120] },
    { y:  0.26, a: 0.12, f: 0.0036, s: 0.28, p: 2.1, w: 64, col: BLUE(0.18), dash: [520, 150] }
  ];

  // groups of parallel dashed curves (like your dashed-arc reference)
  const dashed = [
    { y: -0.05, a: 0.16, f: 0.0030, s: 0.30, p: 1.0, n: 4, gap: 20, w: 9,
      pats: [[130, 40], [70, 30], [210, 50], [100, 60]], spd: 26 },
    { y:  0.42, a: 0.10, f: 0.0045, s: 0.40, p: 4.0, n: 3, gap: 18, w: 8,
      pats: [[90, 40], [160, 45], [60, 35]], spd: -22 }
  ];

  function yAt(x, t, r) {
    return r.y * H +
      r.a * H * Math.sin(x * r.f + t * r.s + r.p) +
      r.a * 0.45 * H * Math.sin(x * r.f * 2.3 - t * r.s * 1.4 + r.p);
  }

  function trace(t, r, off) {
    ctx.beginPath();
    for (let x = -L / 2; x <= L / 2; x += 14) {
      const y = yAt(x, t, r) + off;
      if (x === -L / 2) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
  }

  function draw(time) {
    const t = time / 1000;
    ctx.clearRect(0, 0, W, H);
    ctx.save();
    // slight parallax: ribbons drift as you scroll
    ctx.translate(W / 2, H / 2 - window.scrollY * 0.18);
    ctx.rotate(-0.38);
    ctx.lineCap = "round";
    ctx.lineJoin = "round";

    thick.forEach((r, i) => {
      ctx.lineWidth = r.w;
      ctx.strokeStyle = r.col;
      ctx.setLineDash(r.dash);
      ctx.lineDashOffset = -t * (i ? -18 : 24);
      trace(t, r, 0);
      ctx.stroke();
    });

    dashed.forEach((g) => {
      for (let k = 0; k < g.n; k++) {
        ctx.lineWidth = g.w;
        ctx.strokeStyle = k % 2 ? PALE(0.5) : BLUE(0.55);
        ctx.setLineDash(g.pats[k % g.pats.length]);
        ctx.lineDashOffset = -t * g.spd * (1 + k * 0.25);
        trace(t, g, (k - (g.n - 1) / 2) * g.gap);
        ctx.stroke();
      }
    });

    // little dots and rings riding along the waves
    ctx.setLineDash([]);
    for (let k = 0; k < 5; k++) {
      const r = k % 2 ? dashed[0] : thick[1];
      const x = (((t * (22 + k * 6) + k * L / 5) % L) + L) % L - L / 2;
      const y = yAt(x, t, r) + (k % 2 ? -70 : 70);
      ctx.beginPath();
      ctx.arc(x, y, k % 2 ? 11 : 15, 0, Math.PI * 2);
      if (k % 2) { ctx.fillStyle = BLUE(0.6); ctx.fill(); }
      else { ctx.lineWidth = 3.5; ctx.strokeStyle = PALE(0.7); ctx.stroke(); }
    }
    ctx.restore();
  }

  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    draw(0);
  } else {
    (function loop(now) { draw(now); requestAnimationFrame(loop); })(0);
  }
})();

/* =========================================================
   3. PAGE TRANSITIONS (fade out, then go)
   ========================================================= */
document.querySelectorAll("a[href]").forEach((a) => {
  const href = a.getAttribute("href");
  if (!href || href.startsWith("#") || href.startsWith("http") || href.startsWith("mailto:")) return;
  a.addEventListener("click", (e) => {
    e.preventDefault();
    document.body.classList.add("leaving");
    setTimeout(() => (window.location.href = href), 420);
  });
});

/* =========================================================
   4. SCROLL REVEAL + SKILL BARS
   ========================================================= */
(function () {
  const items = document.querySelectorAll(".reveal");
  if (!items.length) return;
  const io = new IntersectionObserver((entries) => {
    entries.forEach((en) => {
      if (!en.isIntersecting) return;
      en.target.classList.add("in");
      en.target.querySelectorAll(".bar i").forEach((bar) => (bar.style.width = bar.dataset.level + "%"));
      io.unobserve(en.target);
    });
  }, { threshold: 0.15 });
  items.forEach((el) => io.observe(el));
})();

/* =========================================================
   5. WORK PAGE: filters + lightbox
   ========================================================= */
(function () {
  const buttons = document.querySelectorAll(".filters button");
  const works = document.querySelectorAll(".work");
  buttons.forEach((btn) =>
    btn.addEventListener("click", () => {
      buttons.forEach((b) => b.classList.remove("on"));
      btn.classList.add("on");
      const f = btn.dataset.filter;
      works.forEach((w) => w.classList.toggle("hide", f !== "all" && w.dataset.type !== f));
    })
  );

  const lb = document.getElementById("lightbox");
  if (!lb) return;
  const box = lb.querySelector(".box");
  works.forEach((w) =>
    w.addEventListener("click", () => {
      box.innerHTML = "";
      const media = w.querySelector(".thumb, img, video").cloneNode(true);
      if (media.tagName === "VIDEO") { media.controls = true; media.autoplay = true; }
      box.appendChild(media);
      lb.classList.add("open");
    })
  );
  const close = () => { lb.classList.remove("open"); box.innerHTML = ""; };
  lb.querySelector(".close").addEventListener("click", close);
  lb.addEventListener("click", (e) => { if (e.target === lb) close(); });
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") close(); });
})();

/* =========================================================
   7. WALKING CRAB (home page only)
      the crab is cut into pieces (shell + 7 legs with knees),
      and each piece swings smoothly from its joint
   ========================================================= */
(function () {
  if (!document.querySelector(".hero")) return;                       // home page only
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

  const ATLAS = "data:image/png;base64,";

  // ---- tweak the walk here ----
  const SPEED = 95;      // how fast the crab crosses the screen (pixels per second)
  const SWING = 0.19;    // how far each leg swings (radians; bigger = bigger steps)
  const BEND  = 0.18;    // how much the knees fold when a foot lifts
  const LIFT  = 6;       // how high a leg lifts its foot
  const WIDTH = "clamp(105px, 12vw, 165px)";   // size of the crab
  // -----------------------------

  const SC = 0.62, IW = 700, IH = 575, PADC = 26;                      // atlas scale, crab size, room around it
  const META = {"base": [0, 0, 384, 268, 81, 0], "A_up": [387, 0, 92, 137, 78, 291], "A_lo": [0, 271, 68, 76, 0, 403], "B_up": [71, 271, 77, 91, 152, 308], "B_lo": [151, 271, 107, 78, 141, 437], "T1": [261, 271, 37, 84, 230, 366], "T2": [301, 271, 25, 71, 287, 409], "C": [329, 271, 135, 137, 300, 351], "D_up": [0, 411, 98, 122, 354, 341], "D_lo": [101, 411, 129, 58, 492, 481], "E_up": [233, 411, 81, 60, 415, 375], "E_lo": [317, 411, 86, 34, 519, 418]};
  // each leg: upper piece, optional lower piece, hip + knee positions, walking phase, knee direction
  const LEGS = [
    { up: "A_up", lo: "A_lo", hip: [188, 328], knee: [105, 445], ph: 0,         dir:  1 },
    { up: "B_up", lo: "B_lo", hip: [208, 332], knee: [205, 447], ph: Math.PI,   dir:  1 },
    { up: "T1",               hip: [258, 392],                    ph: 0,         dir:  1 },
    { up: "T2",               hip: [302, 432],                    ph: Math.PI,   dir:  1 },
    { up: "C",                hip: [355, 380],                    ph: 0,         dir:  1 },
    { up: "D_up", lo: "D_lo", hip: [385, 372], knee: [503, 490], ph: Math.PI,   dir: -1 },
    { up: "E_up", lo: "E_lo", hip: [442, 405], knee: [527, 438], ph: 0,         dir: -1 }
  ];

  const walker = document.createElement("div");
  walker.className = "crab-walker";
  walker.style.width = WIDTH;
  walker.innerHTML = '<canvas class="crab-canvas" style="display:block;width:100%;height:auto"></canvas><div class="crab-shadow"></div>';
  const cv = walker.querySelector("canvas");
  const shadow = walker.querySelector(".crab-shadow");
  const ctx = cv.getContext("2d");
  document.body.appendChild(walker);

  const atlas = new Image();
  let cssW = 140, scale = 1, omega = 14, running = false;

  function piece(name) {
    const m = META[name];
    ctx.drawImage(atlas, m[0], m[1], m[2], m[3], m[4], m[5], m[2] / SC, m[3] / SC);
  }

  function fit() {
    cssW = walker.offsetWidth || 140;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const total = IW + PADC * 2;
    cv.width = Math.round(cssW * dpr);
    cv.height = Math.round(cssW * dpr * (IH + PADC * 2) / total);
    scale = cv.width / total;
    // match the leg rhythm to the walking speed so the feet don't skate
    const px = cssW / total;                                           // css px per crab px
    const stance = 2 * SWING * 170 * px;                               // how far a foot travels while planted
    omega = (Math.PI * SPEED) / stance;
    shadow.style.marginTop = -(PADC * px * 0.9) + "px";
    shadow.style.width = "62%";
  }

  function draw(t, rest) {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, cv.width, cv.height);
    ctx.setTransform(scale, 0, 0, scale, 0, 0);
    ctx.imageSmoothingQuality = "high";
    const w = omega * t;
    const bob = rest ? 0 : -2.2 * Math.abs(Math.sin(w));               // little hop with each step
    const tilt = rest ? 0 : 0.012 * Math.sin(w);
    // everything pivots around the feet
    ctx.translate(PADC + IW / 2, PADC + IH);
    ctx.rotate(tilt);
    ctx.translate(-IW / 2, -IH + bob);
    ctx.translate(0, 0);
    const pad = PADC; void pad;

    for (const L of LEGS) {
      const phi = w + L.ph;
      const swing = rest ? 0 : SWING * Math.cos(phi);                  // back while planted, forward while lifted
      const lift  = rest ? 0 : Math.max(0, -Math.sin(phi));            // 0 while planted, up to 1 mid-step
      ctx.save();
      ctx.translate(L.hip[0], L.hip[1] - LIFT * lift);
      ctx.rotate(swing);
      ctx.translate(-L.hip[0], -L.hip[1]);
      if (L.lo) {                                                      // lower leg: knee folds up on lift
        ctx.save();
        ctx.translate(L.knee[0], L.knee[1]);
        ctx.rotate(L.dir * BEND * lift);
        ctx.translate(-L.knee[0], -L.knee[1]);
        piece(L.lo);
        ctx.restore();
      }
      piece(L.up);
      ctx.restore();
    }
    piece("base");                                                     // shell + head on top
  }

  let t0 = 0;
  function loop(now) {
    if (!running) return;
    draw((now - t0) / 1000);
    requestAnimationFrame(loop);
  }
  walker._draw = draw; walker._omega = () => omega;                    // handy for testing

  let ready = false, wantWalk = false, started = false;
  function go() {
    if (!ready || !wantWalk || started) return;
    started = true;
    setTimeout(() => {
      const w = walker.offsetWidth || 140;
      const dist = window.innerWidth + w;
      const seconds = dist / SPEED;
      // the crab faces left, so it walks right -> left
      const anim = walker.animate(
        [{ transform: "translateX(0px)" }, { transform: `translateX(${-dist}px)` }],
        { duration: seconds * 1000, easing: "linear", fill: "forwards" }
      );
      running = true; t0 = performance.now(); requestAnimationFrame(loop);
      anim.onfinish = () => { running = false; walker.remove(); };      // gone for good
    }, 0);
  }

  atlas.onload = () => { fit(); draw(0, true); ready = true; go(); };
  atlas.src = ATLAS;
  window.addEventListener("resize", () => { if (ready) { fit(); if (!running) draw(0, true); } });

  // start the moment the black screen begins opening (or right away on a return visit)
  if (!document.body.classList.contains("gated")) { wantWalk = true; go(); }
  else new MutationObserver((m, obs) => {
    if (!document.body.classList.contains("gated")) { obs.disconnect(); wantWalk = true; go(); }
  }).observe(document.body, { attributes: true, attributeFilter: ["class"] });
})();

/* =========================================================
   8. LOGO FINDER: tries logo.png, image.png, etc. until one loads
   ========================================================= */
document.querySelectorAll(".logo-slot img").forEach((img) => {
  const names = (img.dataset.try || "logo.png").split(",");
  let i = 0;
  function next() {
    i++;
    if (i < names.length) img.src = names[i];
    else img.remove();                       // nothing found: keep the word LOGO
  }
  img.addEventListener("error", next);
  if (img.complete && img.naturalWidth === 0) next();   // already failed before this script ran
});
